<?php declare(strict_types=1);
$money=static fn(mixed $v):string=>number_format((float)$v,0,',','.').' ₫';
$pageUrl=static fn(int $page):string=>$baseUrl.'/admin/payment-issues?'.http_build_query(['page'=>$page]);
?>
<header class="resource-header"><div><span class="booking-eyebrow">Hàng chờ vận hành</span><h1>Lỗi payment và refund</h1><p>Chỉ hiển thị payment online thất bại có mã lỗi hoặc refund đang chờ/thất bại.</p></div><span class="queue-count"><strong><?= (int)$pageData['total'] ?></strong> vấn đề</span></header>
<section class="resource-surface"><div class="resource-table-wrap"><table class="resource-table"><thead><tr><th>Booking</th><th>Payment</th><th>Tiền</th><th>Refund</th><th>Cập nhật</th></tr></thead><tbody><?php foreach($pageData['items'] as $issue):?><tr><td><a href="<?= $baseUrl ?>/admin/bookings/<?= rawurlencode((string)$issue['bookingCode']) ?>"><strong><?= $issue['bookingCode'] ?></strong></a><small><?= $issue['propertyName'] ?> · <?= $issue['organizationName'] ?></small></td><td><strong><?= $issue['paymentStatus'] ?></strong><small><?= $issue['lastError']??'Không có mã lỗi' ?> · <?= (int)$issue['attempts'] ?> lần thử</small></td><td>Đã thu <strong><?= $money($issue['paid']) ?></strong><small>Đã hoàn <?= $money($issue['refunded']) ?></small></td><td><span class="booking-status booking-status--<?= strtolower((string)$issue['refundStatus']) ?>"><i></i><?= $issue['refundStatus'] ?></span><small><?= $issue['refundReason']??'—' ?></small></td><td><?= $issue['updatedAt'] ?></td></tr><?php endforeach;?><?php if($pageData['items']===[]):?><tr><td colspan="5"><div class="empty-state">Không có payment/refund cần xử lý.</div></td></tr><?php endif;?></tbody></table></div><footer class="resource-footer booking-pagination"><span>Trang <?= (int)$pageData['page'] ?> / <?= (int)$pageData['pageCount'] ?></span><span class="booking-pagination__links"><?php if($pageData['page']>1):?><a class="button button--secondary button--small" href="<?= $pageUrl((int)$pageData['page']-1) ?>">Trang trước</a><?php endif;?><?php if($pageData['page']<$pageData['pageCount']):?><a class="button button--secondary button--small" href="<?= $pageUrl((int)$pageData['page']+1) ?>">Trang sau</a><?php endif;?></span></footer></section>
